  str_cn12_n41_levelname15 = "ST3 - Festival da Primavera",
  str_cn12_n41_levelname_desc1 = "...",
  str_cn12_n41_levelname_desc2 = "Você recebe uma recepção grandiosa, indicando claramente que o governante do Reino Ji o considera em alta estima, no entanto, a reviravolta dos eventos...",
  str_cn12_n41_levelname_desc3 = "Estalos de fogos de artifício ecoam pelas ruas; o que parecia ser uma simples brincadeira de criança acaba sendo algo mais...",
  str_cn12_n41_levelname_desc4 = "Surge um conflito entre as crianças e um demônio, aparentemente um assunto trivial até que a criatura entra em fúria...",
  str_cn12_n41_levelname_desc5 = "...",
  str_cn12_n41_levelname_desc6 = "Para descobrir como acalmar o demônio enlouquecido, você e Luo Song começam a procurar a garota que encontraram antes...",
  str_cn12_n41_levelname_desc7 = "Guiado por seu poder psíquico, o grupo se aproxima lentamente da fonte da força corruptora na cidade - Rua Yulin.",
  str_cn12_n41_levelname_desc8 = "Dentro do palácio, a transação de canhões costeiros entre o Reino de Ji e o Reino de Ye provoca novas ondas...",
  str_cn12_n41_levelname_desc9 = "Juntos, o Mestre da Guilda Lin e Mu Yuebai revelam a você o passado entre Yoh e a família Lin...",
  str_cn12_n41_levelname_desc10 = "Unidos, os cidadãos da capital decidem expulsar os demônios de uma vez por todas. Com paus e bastões em mãos, eles confrontam os demônios nas ruas.",
  str_cn12_n41_levelname_desc11 = "Dantang, ao esgueirar-se para fora do palácio, se vê cercada por inúmeros espiões, deixando-a incapaz de fazer qualquer movimento...",
  str_cn12_n41_levelname_desc12 = "Você chega à baía e, apesar de advertido por Chen'ni, você e Mu Yuebai se encontram abruptamente envolvidos pelo poder corruptor.",
  str_cn12_n41_levelname_desc13 = "Luo Song e Liqing estão trabalhando juntos para lidar com os demônios afetados pelo esquema dos Cavaleiros do Destino dentro da cidade. Mas, do nada, o céu escurece e ondas imensas obscurecem o céu...",
  str_cn12_n41_levelname_desc14 = "O poder sombrio tentando manejar Yoh finalmente se revela, pois não consegue evitar surgir das profundezas da mente de Yoh.",
  str_cn12_n41_levelname_desc15 = "...",
  str_cn12_n41_levelname16 = "H1 - Abrigo do Perigo",
