  str_cn12_n41_levelname19 = "H4 - Erradicado",
  str_cn12_n41_levelname20 = "EX1-1 - Pregar",
  str_cn12_n41_levelname21 = "EX1-2 - Pregar",
  str_cn12_n41_levelname22 = "EX2-1 - Destemida",
  str_cn12_n41_levelname23 = "EX2-2 - Destemida",
  str_cn12_n41_levelname24 = "EX3-1 - Desejo Concedido",
  str_cn12_n41_levelname25 = "EX3-2 - Desejo Concedido",
  str_cn12_n41_levelname26 = "EX3-3 - Desejo Concedido",
  str_cn12_n41_levelname27 = "EX1 - Pregar",
  str_cn12_n41_levelname28 = "EX2 - Destemida",
  str_cn12_n41_levelname29 = "EX3 - Desejo Concedido",
  str_cn12_n41_levelname_desc16 = "Ondas avançam, a chuva despeja. Os moradores entram em pânico, perto e longe.",
  str_cn12_n41_levelname_desc17 = "Cortando ondas, curando a cicatriz do mal. Donzela dragão, nossa estrela guia.",
  str_cn12_n41_levelname_desc18 = "Mil anos como um sopro, cem anos como uma canção. O mundo testemunha a linha turva entre o certo e o errado.",
  str_cn12_n41_levelname_desc19 = "Anos se despedindo, criaturas malignas permanecem na sombra. A graça da Donzela Dragão protege todas as direções, resplandecente.",
  str_cn12_n41_levelname_desc20 = "EX1-1 - Pregar: Fogo Terrestre",
  str_cn12_n41_levelname_desc21 = "EX1-2 - Pregar: Fogo Celeste",
  str_cn12_n41_levelname_desc22 = "EX2-1 - Destemida: Chuva",
  str_cn12_n41_levelname_desc23 = "EX2-2 - Destemida: Chuva Intensa",
  str_cn12_n41_levelname_desc24 = "EX3-1 - Desejo Concedido: Queda do Trovão",
  str_cn12_n41_levelname_desc25 = "EX3-2 - Desejo Concedido: Resposta do Trovão",
  str_cn12_n41_levelname_desc26 = "EX3-3 - Desejo Concedido: Choque do Trovão",
  str_cn12_n41_1600141_speak = "A riqueza é apenas um meio, não o fim. May que esta fortuna te ajude a alcançar os desejos do seu coração, mestre do Colosso.",
  str_cn12_n41_1602181_speak = "Seu sorteio auspicioso traz uma alegria incomparável para mim. Sinceramente, suas riquezas são, de certa forma, minhas futuras riquezas. Aguardo sua próxima visita!",
  str_cn12_n41_1601811_speak = "Você está no auge do seu vigor, jovem amigo. Este bastão da sorte fala de riqueza, mas riqueza, conexões, oportunidades e ambição são inseparáveis - também é um testemunho de suas habilidades.",
  str_cn12_n41_1601211_speak = "Acreditar que um único bastão da sorte pode trazer riquezas? Isso é muito absurdo! Uh, talvez a mágica esteja na crença. Então, certifique-se de manter seu ânimo elevado!",
  str_cn12_n41_1601121_speak = "Fortuna moderada? Nada mal! Quando você conseguir o dinheiro, vá até Umbraton e compre algumas roupas elegantes, chega desses trajes simples.",
  str_cn12_n41_1500761_speak = "Como o sonho é o oposto da realidade, talvez o mesmo se aplique à adivinhação, certo? Não se preocupe; seja você rico ou pobre, eu estarei sempre aqui nas profundezas do mar, esperando por você, Navegador.",
  str_cn12_n41_1300531_speak = "Ei, chefe, você pegou um palito de fortuna bastante decente aí! Fortuna moderada é perfeita. Você definitivamente vai ganhar um bom dinheiro no próximo ano! Certifique-se de visitar minha loja com frequência!",
  str_cn12_n41_1500841_speak = "Riqueza significa poder em Umbraton, mas se exibir demais convida problemas. O equilíbrio é a chave, e seu palito da sorte parece um bom sinal.",
  str_cn12_n41_1501871_speak = "Oh, Pequena Fortuna. Eu já a tirei duas vezes, e você acabou de tirar a última. Devemos encontrar uma maneira de mudar nossa sorte?",
  str_cn12_n41_1500331_speak = "Hmm... Pequena fortuna... Será que nossas despesas diárias ainda são muito altas? Mas o fato de termos conseguido manter o Colossus em bom estado e ainda ter um excedente já é fantástico o suficiente! Vamos continuar com o bom trabalho no próximo ano também!",
  str_cn12_n41_1300461_speak = "Desejando-lhe uma fortuna, uma vida tão grandiosa. Nos próximos dias, que a alegria se expanda.\nReceba o bem, e que o infortúnio se vá.\nOfereça presentes em abundância, e que nenhum erro te encontre.\nPequena sorte ainda é sorte! Certifique-se de colocar mais no envelope vermelho para mim!",
  str_cn12_n41_1600771_speak = "Você tem o poder de moldar o destino do mundo, então esse resultado é esperado. Não se preocupe; Eu estarei com você em cada passo do caminho.",
  str_cn12_n41_1602161_speak = "Em Longzhou, dizemos que os heróis são \"Abençoados pelo Céu\", ou \"Líderes Natos, Destinados pelos Céus e pela Terra\". Como conversamos na Sala de Recreação, você é exatamente assim, sempre transformando infortúnios em bênçãos, não acha?",
  str_cn12_n41_1601531_speak = "Parece que você está pronto para grandes realizações este ano. Apenas tenha em mente que quanto mais alto você vai, mais deve se cuidar - Grandes árvores atraem mais vento, sabe? E não se esqueça de buscar ajuda de seus parceiros de confiança quando necessário.",
  str_cn12_n41_1601171_speak = "Haha, sua expressão diz tudo! É bom para os jovens terem grandes ambições. Mas lembre-se, além da batalha e do treinamento, a saúde também importa. Quer um pouco de sopa enlatada?",
  str_cn12_n41_1601191_speak = "Grandes visões... o que é isso? Esse bastão da sorte significa que você será mais forte contra os Eclipsitas? Mas ei, o meu diz \"Grande Fortuna\". Heehee, isso é muito mais incrível do que o seu, não é?",
  str_cn12_n41_1600061_speak = "Um resultado satisfatório - não tão desanimador, mas suficiente para acender seu espírito de luta por um futuro mais brilhante. Espero ter um papel nessa versão do seu futuro.",
  str_cn12_n41_1600021_speak = "Tudo neste mundo é inerentemente vazio. Tal consciência é o que ajuda a ultrapassar os próprios limites. May que nossos destinos sejam nossos para comandar.",
  str_cn12_n41_1601291_speak = "Parece que a sorte está do seu lado, querido parceiro. O que, ainda não está satisfeito? Assim que terminar esta missão, vou pintar para você um desenho ainda mais bonito de Grande Fortuna.",
  str_cn12_n41_1600641_speak = "Parabéns, você conseguiu o mesmo que eu - uma pequena fortuna ainda é uma fortuna, não é? Com certeza vamos mudar as coisas este ano! Espere, por que você está fazendo um Namaste assim?",
  str_cn12_n41_1600301_speak = "Te disse para ficar comigo, garoto. Ninguém pode definir seu sucesso, apenas você mesmo! Viva o momento e viva a vida ao máximo!",
  str_cn12_n41_1500551_speak = "Os palitos da sorte são apenas para diversão, então não venha me perguntar como ficar acordado a noite toda. Que tal focar primeiro em ficar em forma, passo a passo?",
  str_cn12_n41_1601881_speak = "Seu bastão diz Grande Fortuna, o que significa que a sorte deve estar ao seu lado. Espere, também diz que sua alma gêmea está bem diante de você... mas somos apenas nós dois aqui - a adivinhação de Li Tianxian é uma total farsa!",
  str_cn12_n41_1602111_speak = "Não acredito que sua vida amorosa é tão promissora! \"Seu parceiro destinado pode estar bem entre seus companheiros\"? Hmm...isso me deixa um pouco animado para nossa próxima viagem, só um pouquinho!",
  str_cn12_n41_1601161_speak = "Você parece estar se tornando mais popular do que eu nos últimos tempos! Mas ei, ser muito popular nem sempre é bom, então cuide-se. E se você precisar se afastar de alguma situação, minha nova Asa de Aço V2 está à sua disposição!",
  str_cn12_n41_1601311_speak = "Parabéns, Vossa Excelência! Encontrar alguém para compartilhar e percorrer a vida juntos é algo realmente comovente e sortudo.",
  str_cn12_n41_1601261_speak = "Histórias de amor na ficção sempre começam como um sonho, são divertidas do início ao fim e têm um final feliz. Acredito que sua vida amorosa será tão perfeita quanto essas histórias.",
  str_cn12_n41_1500991_speak = "O valor que atribuímos aos outros nos faz hesitar em nos aproximar deles, duvidando que podemos tê-los... Mas às vezes você deve ser corajoso, chegar mais perto, estender a mão, para ser feliz, certo?",
  str_cn12_n41_1600261_speak = "Qual é o significado de tudo isso? Tudo é vazio de qualquer maneira... O que, você quer compartilhar essa boa sorte comigo?... Tive essa sensação estranha de repente... Tudo bem, me diga qual bastão da sorte você tirou.",
  str_cn12_n41_1601111_speak = "Não ter medo de se aproximar e fazer conexões com os outros já é uma grande bênção e alegria... Será que eu também posso encontrar essa alegria simples?",
  str_cn12_n41_1602121_speak = "O texto nas varetas de sorte, mesmo aqueles com esperanças depositadas nelas, pode ser interpretado racionalmente! Mas minha pesquisa em psicologia está faltando... Hora de ir à biblioteca para alguns materiais de psicologia romântica... Ops, desculpe, estou pensando alto novamente!",
  str_cn12_n41_1601051_speak = "Depois de dizer que ainda não sou velho o suficiente para essas coisas, meu irmão saiu tempestuosamente com sua chave inglesa. Você pode me dizer se o vir? Obrigado, você é o melhor!",
  str_cn12_n41_1501831_speak = "Sendo o mais velho aqui, eu tirei o mesmo palito de sorte que você. Mas ei, você deveria se preocupar mais com boa comida e em manter-se saudável! Viu? Até o Tinytail concorda, abanando o rabo e tudo mais.",
  str_cn12_n41_litianxian_speak1 = "Ah, aqui está você! Recentemente, encontrei um conjunto requintado de bastões da sorte. Diz-se que o desejo de alguém será revelado pela mensagem no bastão. Gostaria de testar a sorte de hoje?",
  str_cn12_n41_litianxian_speak2 = "Obrigado pelo seu patrocínio! Que May todos os seus desejos se tornem realidade! Por favor, volte outro dia, e então podemos discutir as fortunas juntos!",
  str_cn12_n41_game_title_tip = "Por favor, selecione a sorte que deseja receber.",
  str_cn12_n41_game_luck3 = "Grande Fortuna",
  str_cn12_n41_game_luck2 = "Fortuna moderada",
