  str_cn12_n41_game_tip2 = "Restante Hoje: {1}",
  str_cn12_n41_game_tip3 = "Por favor, selecione o aspecto em que sua sorte será prevista.",
  str_cn12_n41_game_tip4 = "Confirma a seleção de <color=#962b1c>{1}</color>?",
  str_cn12_n41_game_tip5 = "Por favor, selecione um aspecto.",
